const body = $json.body ?? $json;

const prediction = body.prediction;
const user = body.user_data;
const shap = body.shap;

// -----------------------------
// 1. Validaciones mínimas
// -----------------------------

if (!prediction || !user || !shap) {
  throw new Error("El JSON recibido no contiene prediction, user_data o shap.");
}

// El RAG solo debería ejecutarse para casos por debajo del umbral.
// Si llega uno por encima, mejor detener el flujo.
if (prediction.probability >= prediction.threshold) {
  throw new Error(
    "La probabilidad es igual o superior al umbral. Este caso no debe ser procesado por el RAG."
  );
}

// -----------------------------
// 2. Interpretación de variables
// -----------------------------

const genderMap = {
  1: "mujer",
  2: "hombre"
};

const yesNoMap = {
  0: "no",
  1: "sí"
};

const smokeMap = {
  0: "no fumador",
  1: "fumador"
};

const activityMap = {
  0: "inactivo",
  1: "activo"
};

const alcoholMap = {
  0: "no consume alcohol",
  1: "consume alcohol"
};

function interpretFeature(feature, value) {
  switch (feature) {
    case "gender":
      return genderMap[value] ?? `valor desconocido (${value})`;

    case "smoke":
      return smokeMap[value] ?? `valor desconocido (${value})`;

    case "active":
      return activityMap[value] ?? `valor desconocido (${value})`;

    case "alco":
      return alcoholMap[value] ?? `valor desconocido (${value})`;

    case "ap_hi":
      return `${value} mmHg de presión arterial sistólica`;

    case "ap_lo":
      return `${value} mmHg de presión arterial diastólica`;

    case "age_years":
      return `${value} años`;

    case "height":
      return `${value} cm`;

    case "weight":
      return `${value} kg`;

    case "bmi":
      return `IMC de ${value}`;

    default:
      return String(value);
  }
}

// -----------------------------
// 3. Cercanía al umbral
// -----------------------------

const probability = Number(prediction.probability);
const threshold = Number(prediction.threshold);

const distanceToThreshold = threshold - probability;
const thresholdRatio = probability / threshold;

let thresholdProximity;

if (thresholdRatio >= 0.9) {
  thresholdProximity = "muy próximo al umbral";
} else if (thresholdRatio >= 0.7) {
  thresholdProximity = "próximo al umbral";
} else {
  thresholdProximity = "alejado del umbral";
}

// -----------------------------
// 4. Procesamiento de SHAP
// -----------------------------

const topFactors = Array.isArray(shap.top_factors)
  ? shap.top_factors
  : [];

const interpretedFactors = topFactors.map((factor, index) => {
  return {
    priority: index + 1,
    feature: factor.feature,
    raw_value: factor.value,
    interpreted_value: interpretFeature(
      factor.feature,
      factor.value
    ),
    shap_value: factor.shap_value,
    direction: factor.direction
  };
});

const shapText = interpretedFactors
  .map(factor => {
    const directionText =
      factor.direction === "increase"
        ? "aumentó la predicción"
        : factor.direction === "decrease"
        ? "disminuyó la predicción"
        : factor.direction;

    return `${factor.priority}. ${factor.feature}
- Valor: ${factor.interpreted_value}
- Impacto SHAP: ${factor.shap_value}
- Efecto: ${directionText}`;
  })
  .join("\n\n");

// -----------------------------
// 5. Construcción del input para el RAG
// -----------------------------

const input = `
Analiza el siguiente perfil cardiovascular y genera recomendaciones educativas personalizadas utilizando únicamente la información contenida en los documentos recuperados.

RESULTADO DEL MODELO

- Probabilidad estimada: ${(probability * 100).toFixed(1)}%
- Umbral de decisión del modelo: ${(threshold * 100).toFixed(1)}%
- Clasificación del modelo: ${prediction.classification}
- Versión del modelo: ${prediction.model_version}
- Distancia al umbral: ${(distanceToThreshold * 100).toFixed(1)} puntos porcentuales
- Relación respecto al umbral: ${(thresholdRatio * 100).toFixed(1)}%
- Situación respecto al umbral: ${thresholdProximity}

La probabilidad está por debajo del umbral de decisión utilizado por PULSO.
La cercanía al umbral debe utilizarse únicamente para ajustar la prioridad y prudencia de las recomendaciones.
No debe interpretarse como una categoría clínica ni como diagnóstico.

DATOS DEL USUARIO

- Sexo: ${genderMap[user.gender] ?? "desconocido"}
- Edad: ${user.age_years} años
- Altura: ${user.height} cm
- Peso: ${user.weight} kg
- IMC: ${user.bmi}
- Presión arterial sistólica: ${user.ap_hi} mmHg
- Presión arterial diastólica: ${user.ap_lo} mmHg
- Tabaquismo: ${smokeMap[user.smoke] ?? "desconocido"}
- Consumo de alcohol: ${alcoholMap[user.alco] ?? "desconocido"}
- Actividad física: ${activityMap[user.active] ?? "desconocido"}

PRINCIPALES FACTORES IDENTIFICADOS POR SHAP

${shapText}

INSTRUCCIONES PARA LA RESPUESTA

- Genera recomendaciones educativas de prevención cardiovascular.
- Utiliza únicamente información respaldada por los documentos recuperados.
- Prioriza especialmente los factores que SHAP identificó como contribuyentes al aumento de la predicción.
- Ten en cuenta qué tan cerca está la probabilidad del umbral.
- Si el resultado está muy próximo al umbral, utiliza un tono más prudente y enfatiza el seguimiento de los factores modificables.
- Si está alejado del umbral, mantén un enfoque preventivo y educativo.
- No recalcules la probabilidad.
- No modifiques la clasificación.
- No diagnostiques enfermedades.
- No afirmes que estar cerca del umbral significa tener una enfermedad.
- No presentes el umbral como una frontera clínica.
- No inventes información.
- Si los documentos recuperados no contienen evidencia suficiente para recomendar algo sobre un factor, indícalo.
`;

// -----------------------------
// 6. Salida del nodo
// -----------------------------

return {
  json: {
    chatInput: input,

    prediction_context: {
      probability,
      threshold,
      classification: prediction.classification,
      threshold_proximity: thresholdProximity
    },

    interpreted_user_data: {
      gender: genderMap[user.gender] ?? "desconocido",
      age_years: user.age_years,
      bmi: user.bmi,
      systolic_pressure: user.ap_hi,
      diastolic_pressure: user.ap_lo,
      smoking: smokeMap[user.smoke] ?? "desconocido",
      alcohol: alcoholMap[user.alco] ?? "desconocido",
      physical_activity: activityMap[user.active] ?? "desconocido"
    },

    interpreted_shap: {
      top_factors: interpretedFactors
    }
  }
};

// =====================================================
// PULSO - Preparar contexto documental y fuentes
// =====================================================

// Recuperar directamente los resultados del nodo Supabase
const supabaseItems = $("Supabase Vector Store").all();

// Recuperar el perfil preparado por el primer Code
const original = $("Code in JavaScript").first().json;

// =====================================================
// 1. Inicializar estructuras
// =====================================================

const sourceMap = {};
const contextParts = [];

let sourceCounter = 1;

// =====================================================
// 2. Procesar resultados recuperados desde Supabase
// =====================================================

for (const item of supabaseItems) {

  const result = item.json ?? {};

  // Estructura esperada:
  // {
  //   document: {
  //     pageContent: "...",
  //     metadata: {...}
  //   },
  //   score: 0.72
  // }

  const document = result.document;

  if (
    !document ||
    typeof document.pageContent !== "string" ||
    document.pageContent.trim() === ""
  ) {
    continue;
  }

  const sourceId = `SOURCE_${sourceCounter}`;

  const metadata = document.metadata ?? {};

  const source =
    metadata.source ??
    "Fuente no identificada";

  const score =
    typeof result.score === "number"
      ? result.score
      : null;

  const lines =
    metadata.loc?.lines ?? null;

  // ===================================================
  // Relación interna controlada por PULSO
  // ===================================================

  sourceMap[sourceId] = {
    source,
    score,
    lines
  };

  // ===================================================
  // Fragmento que verá el LLM
  // ===================================================

  contextParts.push(
`[${sourceId}]
${document.pageContent.trim()}`
  );

  sourceCounter++;
}

// =====================================================
// 3. Validación
// =====================================================

if (contextParts.length === 0) {
  throw new Error(
    `El nodo Supabase devolvió ${supabaseItems.length} resultados, ` +
    `pero ninguno contiene document.pageContent válido.`
  );
}

// =====================================================
// 4. Construcción del contexto documental
// =====================================================

const context =
  contextParts.join("\n\n---\n\n");

// =====================================================
// 5. Salida final
// =====================================================

return [
  {
    json: {

      // Perfil cardiovascular
      chatInput:
        original.chatInput,

      prediction_context:
        original.prediction_context,

      interpreted_user_data:
        original.interpreted_user_data,

      interpreted_shap:
        original.interpreted_shap,

      // Contexto para el LLM
      context,

      // Mapa real de fuentes
      sourceMap,

      // Información para evaluación del retrieval
      retrieval_info: {
        documents_retrieved:
          contextParts.length,

        source_ids:
          Object.keys(sourceMap),

        scores:
          Object.entries(sourceMap).map(
            ([source_id, data]) => ({
              source_id,
              score: data.score
            })
          )
      }
    }
  }
];

// =====================================================
// PULSO - Validar y resolver fuentes del LLM
// =====================================================

// Salida del Basic LLM Chain
const llmItem = $input.first().json;

// Mapa real de fuentes generado antes del LLM
const sourceMap =
  $("Preparar contexto y fuentes").first().json.sourceMap;

// =====================================================
// 1. Obtener y parsear respuesta del LLM
// =====================================================

const rawText = llmItem.text;

if (!rawText || typeof rawText !== "string") {
  throw new Error(
    "El LLM no devolvió un campo 'text' válido."
  );
}

let parsed;

try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error(
    "La respuesta del LLM no contiene un JSON válido."
  );
}

// =====================================================
// 2. Validar estructura mínima
// =====================================================

if (!Array.isArray(parsed.recommendations)) {
  throw new Error(
    "La respuesta del LLM no contiene un arreglo 'recommendations'."
  );
}

// =====================================================
// 3. Validar SOURCE_X y resolver fuentes reales
// =====================================================

const validatedRecommendations = [];

for (const recommendation of parsed.recommendations) {

  const sourceIds = Array.isArray(recommendation.source_ids)
    ? recommendation.source_ids
    : [];

  // Solamente aceptar SOURCE_X que realmente existan
  const validSourceIds = sourceIds.filter(
    id => sourceMap[id]
  );

  // Si la recomendación no tiene ninguna fuente válida,
  // no debe llegar al usuario
  if (validSourceIds.length === 0) {
    continue;
  }

  const sources = validSourceIds.map(id => ({
    source_id: id,
    source: sourceMap[id].source,
    score: sourceMap[id].score,
    lines: sourceMap[id].lines
  }));

  validatedRecommendations.push({
    factor: recommendation.factor,
    recommendation: recommendation.recommendation,
    source_ids: validSourceIds,
    sources
  });
}

// =====================================================
// 4. Determinar si quedó información utilizable
// =====================================================

const insufficientInformation =
  parsed.insufficient_information === true ||
  validatedRecommendations.length === 0;

// =====================================================
// 5. Generar salida final
// =====================================================

return [
  {
    json: {
      summary: insufficientInformation
        ? ""
        : parsed.summary ?? "",

      recommendations: validatedRecommendations,

      considerations: insufficientInformation
        ? ""
        : parsed.considerations ?? "",

      note: insufficientInformation
        ? "No hay suficiente información en la base documental para generar recomendaciones respaldadas para este perfil."
        : parsed.note ??
          "PULSO ofrece información educativa y preventiva y no constituye un diagnóstico médico.",

      insufficient_information: insufficientInformation
    }
  }
];
